using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using Frociart;
static class JavaViewerTests {
 static int checks;static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();var d=FlowPseudocode.Decode("LEGGI numero\nSTAMPA numero * 2");byte[] before=DiagramIO.EncodeDocument(d);foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);using(var dialog=new SourceCodeDialog(d,(f,n)=>{},true)){dialog.ShowInTaskbar=false;dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-3000,-3000);dialog.Show();Application.DoEvents();Check(dialog.Source!=null&&dialog.Source.Language=="java","Java produced");Check(dialog.Save.Text.Contains(".java")&&dialog.Text.Contains("Java"),"Java labels and export");Check(!dialog.Editor.Text.Contains("class _fc_Runtime"),"support hidden initially");dialog.Support.Checked=true;Check(dialog.Editor.Text.Contains("class _fc_Runtime"),"complete runtime visible");dialog.Support.Checked=false;var input=d.Nodes.Single(n=>n.Kind==NodeKind.Input);var line=dialog.Source.ForBlock(null,input.Id).First();dialog.Editor.Select(dialog.Editor.GetFirstCharIndexFromLine(line.Number-1),0);Check(dialog.SelectedOrigin().NodeId==input.Id,"Java line maps to input");string output=Path.Combine(args[0],"ui-export","Programma.java");Directory.CreateDirectory(Path.GetDirectoryName(output));SourceCodeDialog.WriteSource(output,dialog.Source.Text);Check(File.ReadAllText(output)==dialog.Source.Text,"full source saved");using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,dialog.Size));image.Save(Path.Combine(args[0],"java-dialog-"+dark+".png"));}dialog.Close();}}Check(before.SequenceEqual(DiagramIO.EncodeDocument(d)),"document unchanged");Console.WriteLine("JAVA_VIEWER PASS checks="+checks);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
